def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator row or column.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            a, b = grid[:r], grid[r + 1:]
            return [
                [2 if a[i][j] != 0 and b[i][j] != 0 else 0
                 for j in range(w)]
                for i in range(min(len(a), len(b)))
            ]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] != 0 for r in range(h)):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            return [
                [2 if a[i][j] != 0 and b[i][j] != 0 else 0
                 for j in range(min(len(a[i]), len(b[i])))]
                for i in range(h)
            ]
